import { LiveFeed } from "march/landing"

// bir el yapımı ürün dükkânının vitrininde canlı satış duvarı: birkaç saniyede bir yeni sipariş
const NAMES = ["Ayşe", "Murat", "Selin", "Emre", "Gül", "Okan", "Nazlı", "Barış"]
const CITIES = ["İzmir", "Ankara", "Bursa", "Eskişehir", "Trabzon", "Antalya"]
const ITEMS = ["seramik kupa", "keten çanta", "el örgüsü atkı", "ahşap kaşık seti", "mum", "deri cüzdan"]
const COLORS = ["brand-orange", "brand-green", "brand-blue", "brand-purple"] as const

const orders = () => {
  let k = 0
  return () => {
    const i = k++, who = NAMES[(i * 3) % NAMES.length]!
    return { id: i, avatar: who[0], title: `${who} bir ${ITEMS[(i * 5) % ITEMS.length]} aldı`, body: CITIES[(i * 7) % CITIES.length], meta: "az önce", color: COLORS[i % COLORS.length] }
  }
}

export function ShopActivity() {
  return <section sx={{ flex: "col", gap: 3 }}>
    <h2>Şu an Atölye Pazarı'nda</h2>
    <p sx={{ color: "muted" }}>Türkiye'nin dört bir yanından el emeği siparişler.</p>
    <LiveFeed variant="wall" next={orders()} every={3000} first={800} max={6} label="Son siparişler"
      pauseLabel="Canlı · durdur" resumeLabel="Durdu · sürdür" />
  </section>
}

import { LiveFeed } from "march/landing"
import { Segmented, Toggle, Button, Card } from "march/ui"

// LiveFeed'in bütün özellikleri bir arada: denetimli liste (items) ve çekilen öğeler (next), aralık, ilk gecikme,
// en çok öğe, satır / duvar, erişilebilir ad, duyuru (live), durdur düğmesi ve iki metni, atan nokta, üstüne gelince
// durma, kendi satır çizimin, geliş ve gidiş hareketi, parıltı, kayma ve sınıf
type Ev = { id: number; avatar: string; title: string; body: string; meta: string }

export function LiveFeedLab() {
  let $events: Ev[] = [{ id: 2, avatar: "B", title: "Burak koşuya katıldı", body: "Kadıköy", meta: "1 dk" }, { id: 1, avatar: "A", title: "Aslı kulüp kurdu", body: "Beşiktaş", meta: "3 dk" }]
  let $n = 3
  let $variant: "list" | "wall" = "list"
  let $auto = false
  let $own = false
  const add = () => { $events = [{ id: $n, avatar: "Y", title: `Yeni olay ${$n}`, body: "Çankaya", meta: "şimdi" }, ...$events]; $n++ }
  let k = 0
  const source = () => ({ id: 1000 + k, avatar: "O", title: `Otomatik olay ${++k}`, body: "Nilüfer", meta: "şimdi" })
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Görünüm" options={[{ value: "list", label: "satırlar" }, { value: "wall", label: "duvar" }]} bind:value={$variant} />
        <Toggle label="Kendi çizimim" bind:value={$own} />
        <Toggle label="Otomatik akış" bind:value={$auto} />
        <Button on:click={add}>Olay ekle</Button>
      </div>
    </Card>
    {() => { const variant = $variant, auto = $auto, own = $own; return <LiveFeed class="lab-lf" variant={variant} items={() => $events} next={auto ? source : undefined}
      every={2000} first={500} max={5} label="Kulüp akışı" live="polite"
      pausable pauseLabel="Canlı · durdur" resumeLabel="Durdu · sürdür" pulse pauseOnHover
      renderItem={own ? (it: Ev) => <span class="lab-own"><b>{it.title}</b> · <small>{it.body}</small></span> : undefined}
      enter="pop" leave="shrink" glow move /> }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { LiveFeedLab } from "./LiveFeedLab.tsx"

// LiveFeedLab'in testleri: kaydedince Testler sekmesinde çalışır
const rows = (s: { all(sel: string): Element[] }) => s.all(".lab-lf .m-lf-item:not(.is-leaving)")

test("akış adlandırılmış bir bölüm; en yenisi üstte", () => {
  const s = renderTest(() => <LiveFeedLab />)
  expect(s.get(".lab-lf")?.getAttribute("aria-label")).toBe("Kulüp akışı")
  expect(rows(s).length).toBe(2)
  expect(rows(s)[0]!.textContent).toContain("Burak koşuya katıldı")
})

test("yeni olay en üste girer", async () => {
  const s = renderTest(() => <LiveFeedLab />)
  await s.click("Olay ekle")
  expect(rows(s).length).toBe(3)
  expect(rows(s)[0]!.textContent).toContain("Yeni olay 3")
})

test("durdur düğmesi kendi metinleriyle açılıp kapanır", async () => {
  const s = renderTest(() => <LiveFeedLab />)
  const b = s.get(".lab-lf .m-lf-pause")!
  expect(b.textContent).toContain("Canlı · durdur")
  await s.click(b)
  expect(s.get(".lab-lf .m-lf-pause")?.textContent).toContain("Durdu · sürdür")
})

test("duvar görünümü ve kendi satır çizimi", async () => {
  const s = renderTest(() => <LiveFeedLab />)
  await s.click("duvar")
  expect(s.get(".lab-lf")?.classList.contains("m-lf-wall")).toBe(true)
  await s.click("Kendi çizimim")
  expect(s.all(".lab-lf .lab-own").length).toBe(2)
})
